create or replace TABLE SZD_PRODUCTION.CORE.T_DIM_CUSTOMS_PRODUCT (
	PRODUCT_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) of the customs product.',
	DWH_VALID_FROM_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record became valid.',
	DWH_VALID_TO_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was no longer valid.',
	DWH_VALID_FG BOOLEAN NOT NULL COMMENT 'An indicator showing the current record in history.',
	SALES_VARIANT_PRODUCT_GROUP_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) of the item family of this product.',
	CUSTOMS_PRODUCT_TYPE_CD VARCHAR(50) NOT NULL COMMENT 'The unique code of the type of the customs_product_type.',
	CUSTOMS_PRODUCT_TYPE_DESCR VARCHAR(250) NOT NULL COMMENT 'Denormalized Attribute - A brief description of the customs product type.',
	ORIGIN_COUNTRY_LOCATION_SID NUMBER(38,0) NOT NULL COMMENT 'Natural Key/Business Key - The unique identifier (surrogate key) of the political country.',
	CONSIGNOR_STREAM_CD VARCHAR(50) NOT NULL COMMENT 'The unique code of the type of the consignor stream.',
	ORIGIN_ISO_COUNTRY_CD VARCHAR(50) NOT NULL COMMENT 'Denormalized Attribute - The ISO code of the origin country.',
	ORIGIN_COUNTRY_NAME_DE VARCHAR(100) NOT NULL COMMENT 'Denormalized Attribute - The german name of the origin country.',
	ORIGIN_COUNTRY_NAME_EN VARCHAR(100) NOT NULL COMMENT 'Denormalized Attribute - The english name of the origin country.',
	CUSTOMS_PRODUCT_NR NUMBER(38,0) NOT NULL COMMENT 'Natural Key/Business Key - The product number of the customs product, depends on the customs product type.',
	CUSTOMS_ADDITIONAL_CD VARCHAR(50) NOT NULL COMMENT 'Natural Key/Business Key - An additional code to the product number (optional)',
	CUSTOMS_CLASSIFICATION_SCHEME_CD VARCHAR(50) NOT NULL COMMENT 'The unique code of the customs classification scheme.',
	CUSTOMS_TARIFF_NUMBER_CD VARCHAR(50) NOT NULL COMMENT 'Natural Key/Business Key - The unique code of the type of the customs tariff number.',
	CUSTOMS_TARIFF_NUMBER_DESCR VARCHAR(250) COMMENT 'Descriptive Attribute - The name of the type of the customs tariff number.',
	FOOD_NONFOOD_TYPE_CD VARCHAR(50) NOT NULL COMMENT 'The unique code of the Food/Nonfood Type.',
	FOOD_NONFOOD_TYPE_NAME VARCHAR(100) NOT NULL COMMENT 'Descriptive Attribute - The name of the Food/Nonfood Type.',
	ALCOHOLIC_BEVERAGE_TAX_RATE_CD VARCHAR(50) NOT NULL COMMENT 'The unique code of the alcoholic beverage tax rate.',
	ALCOHOLIC_BEVERAGE_TYPE_CD VARCHAR(50) NOT NULL COMMENT 'The unique code of the Alcoholic Beverage Type.',
	ALCOHOLIC_BEVERAGE_TYPE_NAME VARCHAR(100) NOT NULL COMMENT 'Descriptive Attribute - The name of the Alcoholic Beverage Type.',
	ALCOHOLIC_BEVERAGE_VOLUME_QTY NUMBER(38,5) COMMENT 'The volume of the bottle/jar of the alcoholic beverage.',
	ALCOHOLIC_BEVERAGE_PCT NUMBER(38,5) COMMENT 'The percentage of alcohol within an alcoholic beverage.',
	ALCOHOLIC_BEVERAGE_DUTY_PER_UNIT_VAL NUMBER(38,5) COMMENT 'The amount of duty per unit (bottle/jar).',
	CUSTOMS_PRODUCT_NAME VARCHAR(250) NOT NULL COMMENT 'Descriptive Attribute - The name/descriptions of the customs product.',
	PREFERENTIAL_ORIGIN_FG BOOLEAN COMMENT 'Descriptive Attribute - Flag that shows whether the supplier can provide proof of preference or not.',
	PARENT_PRODUCT_SID NUMBER(38,0) NOT NULL COMMENT 'The product this customs product refers to (only applicable for WWT customs products).',
	PARENT_PRODUCT_NAME VARCHAR(250) NOT NULL COMMENT 'Descriptive Attribute - The name of product on IAN level.',
	DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was inserted into the table.',
	DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was last modified. (In case the record has not been modified since its creation, dwh_updated is identical to dwh_created.)',
	DWH_SRC_FILE_NAME VARCHAR(500) COMMENT 'Contains the name(s) of the input file(s) that delivered the record. It can be either the full path of the BLOG storage or the shortened file path',
	DWH_SRC_1_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The extraction timestamp of the record from the source',
	constraint PK_DIM_CUSTOMS_PRODUCT primary key (PRODUCT_SID, DWH_VALID_FROM_TMSP)
)COMMENT='Major Dimension - Contains the products in a granularity that the customs authorities can process, consisting of the product number (IAN), an additional optional product code, the customs tariff number and the country of origin. - Source - GS-Upload, Broker Report'
;